Example of plugin Print method

                public override bool Print()
               {
                  base.Print();

                  this._PrintTypePlugin.Log.WriteLine(5, "Entering PrintData");

                  bool ReturnValue = true;

                  try
                  {
                      //Construct row(s) for print table here
                     ArrayList RowToImport = new ArrayList();
                     this._PrintTypePlugin.PrintData = new DataTable("LabelTableName");

                     CreateAdditionalDataColumns();
                     //Gets additional data from AdditionalPrintData table filled during workflow
                     GetAdditionalData(ref RowToImport, null);
                      if (this._AvailableTablesToPrint.Tables.Contains("BusinessDataTable"))
                      {
                         foreach (DataColumn dc in this._AvailableTablesToPrint.Tables["BusinessDataTable"].Columns)
                         {
                            this._PrintTypePlugin.PrintData.Columns.Add(dc.Table.TableName + "_" + dc.ColumnName);
                            RowToImport.Add(this._AvailableTablesToPrint.Tables["BusinessDataTable"].Rows[0][dc.ColumnName].ToString().Trim());
                         }
                      }
                                  this._PrintTypePlugin.PrintData.LoadDataRow(RowToImport.ToArray(), true);

                     if (this._PrintTypePlugin.DropDataFile())
                        ReturnValue = true;
                     else
                        ReturnValue = false;

                  }
                  catch (exception ex)
                  {
                     this._ErrorMessageVocabulary = "FAILEDTOPRINT";
                     this._PrintTypePlugin.Log.LogException(ex);
                  }

                  this._PrintTypePlugin.Log.WriteLine(5,
                           "Leaving PrintData with RetValue: " + ReturnValue);
                  return ReturnValue;
             }

Use of DropDataFile within Plugin.

               //Check and make sure data is available to print
               bool ReturnValue = true;
               if (_PrintData == null ||
               _PrintData.Rows.Count == 0 ||
               _PrintData.Columns.Count == 0)
               {
                  ReturnValue = false;
                  _ErrorMessageVocabulary = "NODATATOPRINT";
               }
               else
               {
                  //Drop file create
                   _DropFileExtension = ".txt";
                  CreateFile();
                  _DropFileText.Append("Some Format:");
                  foreach (DataRow PrintRow in this._PrintData.Rows)
                  {
                     foreach (DataColumn PrintColumn in _PrintData.Columns)
                     {
                           _DropFileText.Append("Column:" + PrintColumn.ColumnName);
                           _DropFileText.Append(Environment.NewLine);
                           _DropFileText.Append("Value:" + PrintRow[PrintColumn.ColumnName]);
                     }
                  }

                  //Base Call to write out drop file
                  WriteFile();

                  //or execute Print software api calls
                  SomeAPICall.Initialize();

                  foreach (DataRow PrintRow in this._PrintData.Rows)
                  {
                     foreach (DataColumn PrintColumn in _PrintData.Columns)
                     {
                           SomeAPICall.FieldAndData(PrintColumn.ColumnName,
                                 PrintRow[PrintColumn.ColumnName]);
                     }
                  }

                  SomeAPICall.Print();
               }
